var babelJest = require("babel-jest");
var transformer = babelJest.createTransformer
  ? babelJest.createTransformer()
  : babelJest;

function configWithCwd(config) {
  config = config || {};

  if (config.cwd) {
    return config;
  }

  var nextConfig = {};
  Object.keys(config).forEach(function(key) {
    nextConfig[key] = config[key];
  });
  nextConfig.cwd = config.rootDir || process.cwd();

  return nextConfig;
}

function transformOptions(config, options) {
  options = options || {};

  var nextOptions = {};
  Object.keys(options).forEach(function(key) {
    nextOptions[key] = options[key];
  });

  nextOptions.config = configWithCwd(options.config || config);
  nextOptions.rootDir = options.rootDir || nextOptions.config.rootDir;

  return nextOptions;
}

module.exports = {
  canInstrument: transformer.canInstrument,

  getCacheKey: function(fileData, filename, configString, options) {
    var config = {
      rootDir: options && options.rootDir,
      cwd: options && options.rootDir
    };

    return transformer.getCacheKey(
      fileData,
      filename,
      configString,
      transformOptions(config, options)
    );
  },

  process: function(src, filename, config, options) {
    return transformer.process(
      src,
      filename,
      configWithCwd(config),
      transformOptions(config, options)
    );
  }
};

